PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?paper ?year ?stat_method WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C27001 .
  ?paper orkgp:P29 ?year .
  ?contribution orkgp:P135046 ?venue .
  ?venue rdfs:label ?venue_name .
  FILTER(LCASE(STR(?venue_name)) = LCASE("IEEE International Requirements Engineering Conference"))
  ?contribution orkgp:P15124 ?da .
  ?da rdfs:label ?da_label .
  FILTER(LCASE(STR(?da_label)) != LCASE("no analysis"))
  { ?da orkgp:P56043 ?inf . ?inf orkgp:P35133 ?test . ?test rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P56049 ?freq . ?freq orkgp:P55023 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P56049 ?freq . ?freq orkgp:P56050 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P57005 ?ct . ?ct orkgp:P47000 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P57005 ?ct . ?ct orkgp:P57006 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P57005 ?ct . ?ct orkgp:P57007 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P57008 ?disp . ?disp orkgp:P4013 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P57008 ?disp . ?disp orkgp:P57009 ?m . ?m rdfs:label ?stat_method . }
  UNION
  { ?da orkgp:P56048 ?desc . ?desc orkgp:P57008 ?disp . ?disp orkgp:P44087 ?m . ?m rdfs:label ?stat_method . }
}
